<?php use App\Services\ContentImageService as Images; ?>
<fieldset class="wide cover-editor" data-cover-editor data-error="<?= e(tr('Choose an image under 2 MB.')) ?>"><legend><?= e(tr('Cover image optional')) ?></legend><?= Images::thumbnail(isset($row['cover_asset_id'])?(int)$row['cover_asset_id']:null,tr('Cover preview')) ?><label><?= e(tr('Upload cover image')) ?><input type="file" name="cover_image" accept="image/jpeg,image/png,image/webp"<?= Images::ready()?'':' disabled' ?>></label><small><?= e(tr('JPG, PNG or WebP · maximum 2 MB. The image will be optimized.')) ?></small><?php if(!empty($row['cover_asset_id'])): ?><label class="check"><input type="checkbox" name="remove_cover" value="1"><?= e(tr('Remove cover image')) ?></label><?php endif; ?><?php if(!Images::ready()): ?><p role="status"><?= e(tr('Cover image migration is awaiting approval.')) ?></p><?php endif; ?></fieldset>
